  const overlay = document.querySelector('[class*="modal"], [class*="Modal"], [class*="overlay"], [role="dialog"]');
  return JSON.stringify({
    dialogTextPresent: dialogVisible,
    overlayFound: !!overlay,
    overlayVisible: overlay ? (overlay.offsetParent !== null || getComputedStyle(overlay).display !== 'none') : false,
    time: new Date().toISOString()
  });
}

