() => {
  const text = document.body.innerText;
  const dialogTextPresent = text.includes('PDF GENERATOR') || text.includes('立即编译导出高清 PDF');
  // check for any visible fixed overlay
  const fixedEls = Array.from(document.querySelectorAll('body *')).filter(el => {
    const s = getComputedStyle(el);
    return (s.position === 'fixed' || s.position === 'absolute') && parseInt(s.zIndex || '0') >= 100 && el.offsetParent !== null;
  }).map(el => ({tag: el.tagName, cls: (el.className||'').toString().slice(0,80), text: (el.innerText||'').slice(0,60)}));
  return JSON.stringify({dialogTextPresent, fixedEls, time: new Date().toISOString()});
}

() => {
  // Look for toast messages or progress indicators
  const text = document.body.innerText;
  const hasToast = /导出|编译|生成中|成功|失败|PDF/i.test(text) ? text.match(/[^\n]{0,60}(导出|编译|成功|失败)[^\n]{0,60}/g) : null;
  const busy = !!document.querySelector('[class*="spin"], [class*="load"], [class*="progress"]');
  return JSON.stringify({hasToast, busy});
}

() => {
  if (window.__pdfProbe) return 'already installed';
  window.__pdfProbe = { downloads: [], dialogEvents: [] };
  // intercept anchor clicks
  const origClick = HTMLAnchorElement.prototype.click;
  HTMLAnchorElement.prototype.click = function() {
    try {
      window.__pdfProbe.downloads.push({
        href: (this.href || '').slice(0, 80),
        download: this.download || '',
        time: new Date().toISOString()
      });
    } catch(e) {}
    return origClick.apply(this, arguments);
  };
  const origCreate = URL.createObjectURL.bind(URL);
  URL.createObjectURL = function(obj) {
    try {
      window.__pdfProbe.downloads.push({
        createObjectURL: true,
        type: obj && obj.type,
        size: obj && obj.size,
        time: new Date().toISOString()
      });
    } catch(e) {}
    return origCreate(obj);
  };
  // watch dialog presence
  const obs = new MutationObserver(() => {
    const present = document.body.innerText.includes('PDF GENERATOR');
    const last = window.__pdfProbe.dialogEvents[window.__pdfProbe.dialogEvents.length-1];
    if (!last || last.present !== present) {
      window.__pdfProbe.dialogEvents.push({present, time: new Date().toISOString()});
    }
  });
  obs.observe(document.body, {childList: true, subtree: true});
  return 'probe installed';
}

