async () => {
  const start = Date.now();
  const timeline = [];
  let dialogGoneAt = null;
  for (let i = 0; i < 120; i++) { // up to ~12s
    const present = document.body.innerText.includes('PDF GENERATOR');
    timeline.push({t: Date.now() - start, present});
    if (!present && dialogGoneAt === null) dialogGoneAt = Date.now() - start;
    await new Promise(r => setTimeout(r, 100));
    if (dialogGoneAt !== null && Date.now() - start > dialogGoneAt + 3000) break;
  }
  return JSON.stringify({
    dialogGoneAtMs: dialogGoneAt,
    probeDownloads: window.__pdfProbe ? window.__pdfProbe.downloads : null,
    dialogEvents: window.__pdfProbe ? window.__pdfProbe.dialogEvents : null
  });
}

